from __future__ import annotations

from abc import ABC, abstractmethod
from typing import Any, Callable


class DataProcessor(ABC):
    @abstractmethod
    def process(self, data: list[Any]) -> list[Any]:
        ...


class BaseProcessor(DataProcessor):
    def process(self, data: list[Any]) -> list[Any]:
        return list(data)


class ProcessorDecorator(DataProcessor):
    def __init__(self, wrapped: DataProcessor) -> None:
        self._wrapped = wrapped

    def process(self, data: list[Any]) -> list[Any]:
        return self._wrapped.process(data)


class FilterProcessor(ProcessorDecorator):
    def __init__(self, wrapped: DataProcessor, predicate: Callable[[Any], bool]) -> None:
        super().__init__(wrapped)
        self._predicate = predicate

    def process(self, data: list[Any]) -> list[Any]:
        return [item for item in self._wrapped.process(data) if self._predicate(item)]


class TransformProcessor(ProcessorDecorator):
    def __init__(self, wrapped: DataProcessor, func: Callable[[Any], Any]) -> None:
        super().__init__(wrapped)
        self._func = func

    def process(self, data: list[Any]) -> list[Any]:
        return [self._func(item) for item in self._wrapped.process(data)]


if __name__ == "__main__":
    processor = TransformProcessor(
        FilterProcessor(BaseProcessor(), lambda x: x > 0),
        lambda x: x * 2,
    )
    print(processor.process([-1, 0, 1, 2, 3]))  # [2, 4, 6]

