from __future__ import annotations

from typing import Any, Callable


class DataProcessor:
    def __init__(self, config: dict[str, Any]) -> None:
        self.config = config
        self._transform_cache: dict[int, Any] = {}

    def _cached_transform(self, item: Any) -> Any:
        key = id(item)
        cached = self._transform_cache.get(key)
        if cached is not None:
            return cached
        result = self.config["transform"](item)
        self._transform_cache[key] = result
        return result

    def process(self, data: list[Any]) -> list[Any]:
        result = []
        for item in data:
            if self.config.get("filter"):
                if not self.config["filter"](item):
                    continue
            transformed = item
            if self.config.get("transform"):
                transformed = self._cached_transform(item)
            result.append(transformed)
        return result

